local function LANGF() return qa.cfg.lang or "eng" end
local Q = { stage = 0 }

local function has_high(s)
	for i = 1, #s do if string.byte(s, i) >= 0xA8 then return true end end
	return false
end

qa.once("rq_loc_ids", function(t, lo)
	if IsDedicatedServer() or lo == nil then return end
	local LANG = LANGF()
	local bad, n, utf8n = {}, 0, 0
	for _, row in ipairs(IDS) do
		local id, en, ru, ru8 = row[1], row[2], row[3], row[4]
		local s = game.translate_string(id)
		n = n + 1
		local ok
		if LANG == "rus" then
			if s == ru then ok = true
			elseif s == ru8 then ok = true utf8n = utf8n + 1
			else ok = false end
			if ok and (s == id or not has_high(s)) then ok = false end
		else
			ok = (s == en)
		end
		if not ok then bad[#bad + 1] = id .. "=>" .. tostring(s) end
	end
	local detail = n .. " ids, lang " .. LANG .. ", utf8-form " .. utf8n .. (#bad > 0 and (", first bad: " .. table.concat(bad, " | ", 1, math.min(#bad, 4))) or "")
	qa.assert("all " .. n .. " repeatable_quests ids translate (" .. LANG .. ")", #bad == 0 and n > 150, detail)
	-- the strings FOSTER reported in English
	local want = {
		rq_ask_work = "ask_work", rq_npc_work = "npc_work", rq_sid_camp_offer = "camp", rq_sid_kill_offer = "kill",
		rq_sid_defend_offer = "defend", rq_not_now = "not_now",
	}
	for id, tag in pairs(want) do
		local s = game.translate_string(id)
		local ok
		if LANG == "rus" then ok = (s ~= id) and has_high(s) and not string.find(s, "[A-Za-z]") else ok = (s ~= id) and string.find(s, "[A-Za-z]") ~= nil end
		qa.assert("FOSTER string " .. id .. " (" .. LANG .. ")", ok, tostring(s))
		qa.event("TXT " .. id .. " = " .. tostring(s))
	end
	-- the other languages' sanity: the id of a base string must also resolve (rus.db / eng.db mounted) or stay the id (override run)
	qa.event("base string st_tip = " .. tostring(game.translate_string("st_tip")))
end)

local function find_sid()
	for id = 1, 65534 do
		local o = level.object_by_id(id)
		if o ~= nil and string.find(o:name(), "sidorovich", 1, true) then return o end
	end
end

local function shot(tag)
	pcall(function() get_console():execute("screenshot jpg") end)
	qa.event("SHOT " .. tag)
end

qa.hooks.rq_loc_talk = function(t, lo)
	if OnServer() and not Q.srv and t > 5 then
		do
			Q.srv = true
			for id = 1, 65534 do
				local o = alife():object(id)
				if o ~= nil and string.find(o:name(), "sidorovich", 1, true) then
					qa.event(string.format("SERVER sid %s id %d pos %.1f %.1f %.1f", o:name(), id, o.position.x, o.position.y, o.position.z))
				end
			end
		end
	end
	if IsDedicatedServer() then return end
	if lo == nil or level.name() ~= "coop_l01_escape" then return end
	if Q.stage == 0 and t > 12 then
		Q.stage = 1
		Q.t1 = t
		pcall(function() lo:set_actor_position(vector():set(-243.0, -24.2, -135.0)) end)
		qa.event("client teleport to the trader bunker")
	elseif Q.stage == 1 and t > Q.t1 + 8 then
		Q.sid = find_sid()
		qa.assert("Sidorovich online on the client", Q.sid ~= nil, Q.sid and Q.sid:name() or "nil")
		Q.stage = 2
		Q.t2 = t
		if Q.sid then
			local p = Q.sid:position()
			qa.event(string.format("CLIENT sid pos %.1f %.1f %.1f", p.x, p.y, p.z))
			pcall(function() lo:set_actor_position(p:add(Q.sid:direction():mul(1.5))) end)
		else
			Q.stage = 9
		end
	elseif Q.stage == 2 and t > Q.t2 + 6 then
		Q.stage = 3
		Q.t3 = t
		local ok, err = pcall(function() lo:run_talk_dialog(Q.sid, false) end)
		qa.event("run_talk_dialog " .. tostring(ok) .. " " .. tostring(err))
	elseif Q.stage == 3 and t > Q.t3 + 4 then
		Q.stage = 4
		local okt, talking = pcall(function() return lo:is_talking() end)
		qa.event("is_talking " .. tostring(okt) .. " " .. tostring(talking))
		qa.assert("talk window opens with Sidorovich", okt and talking == true, tostring(talking))
		shot("sid_talk_" .. LANGF())
	elseif Q.stage == 4 and t > Q.t3 + 8 then
		Q.stage = 5
		pcall(function() lo:stop_talk() end)
		pcall(function() Q.sid:stop_talk() end)
	end
end
